#include "NeuralChipSafetySupervisor.h"
namespace dnxr { NeuralChipSafetyDecision NeuralChipSafetySupervisor::evaluate(const NeuralChipAck& a,bool firmwareMatch,int lost) const { NeuralChipSafetyDecision d; if(!firmwareMatch){d.reason="firmware_mismatch";return d;} if(a.hardwareCutoffActive){d.reason="hardware_cutoff_active";return d;} if(a.deviceTemperature>41.0f){d.reason="device_temperature_high";return d;} if(a.latencyMeasuredMs>20.0f||lost>2){d.action=NeuralChipSafetyAction::HoldLastSafeFrame;d.reason="latency_or_packet_loss";return d;} if(a.signalQuality<0.3f){d.action=NeuralChipSafetyAction::RealityAnchor;d.reason="low_signal_quality";return d;} d.allowed=true; d.action=NeuralChipSafetyAction::Allow; d.reason="chip_safe"; return d; } }
